<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require __DIR__.'/coa_client.php';if($_SERVER['REQUEST_METHOD']!=='POST')json_response(array('ok'=>false,'error'=>'Método não permitido.'),405);
try{require_csrf((string)($_POST['csrf']??''));$login=valid_login((string)($_POST['login']??''));$c=addon_config();$nas=(string)($c['nas_ip']??'');if(!filter_var($nas,FILTER_VALIDATE_IP))throw new RuntimeException('NAS-IP-Address do Huawei não configurado.');$d=db();$st=$d->prepare("SELECT acctsessionid,framedipaddress,nasipaddress FROM radacct WHERE LOWER(username)=LOWER(?) AND nasipaddress=? ORDER BY radacctid DESC LIMIT 1");$st->bind_param('ss',$login,$nas);$st->execute();$session=$st->get_result()->fetch_assoc();$st->close();if(!$session)throw new RuntimeException('Sessão Huawei não localizada no RADIUS.');$secret=coa_secret($d,$nas);$d->close();$r=coa_send($nas,$secret,array('User-Name'=>$login,'Acct-Session-Id'=>(string)$session['acctsessionid'],'Framed-IP-Address'=>(string)$session['framedipaddress'],'NAS-IP-Address'=>$nas));if(!$r['ok']){if($r['nak'])throw new RuntimeException('Huawei respondeu Disconnect-NAK e recusou a sessão. Confira os atributos CoA e o radius-server authorization.');throw new RuntimeException('Sem resposta CoA do Huawei na porta 3799.');}json_response(array('ok'=>true,'message'=>'Disconnect-ACK confirmado: '.$login.' foi desconectado via RADIUS CoA.'));}catch(Throwable$e){json_response(array('ok'=>false,'error'=>'Falha ao desconectar via CoA: '.$e->getMessage()),422);}
